package deploy

import (
	"context"
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"path"
	"regexp"
	"strconv"
	"strings"
	"time"
)

//go:embed scripts
var deploySources embed.FS

// Script files are shipped with the executor. Keep their whitespace intact:
// command hashes and submitted job snapshots depend on the generated bytes.
func deployScript(name string) string {
	data, err := deploySources.ReadFile("scripts/" + name)
	if err != nil {
		panic(fmt.Sprintf("missing deploy source %q: %v", name, err))
	}
	return strings.ReplaceAll(string(data), "\r\n", "\n")
}

func deployTemplate(name string, args ...any) string {
	return fmt.Sprintf(deployScript(name), args...)
}

var deployCommands = func() map[string][]string {
	commands := map[string][]string{}
	err := fs.WalkDir(deploySources, "scripts", func(name string, entry fs.DirEntry, err error) error {
		if err != nil || entry.IsDir() || path.Base(name) != "commands.json" {
			return err
		}
		var definitions map[string][]string
		if err := json.Unmarshal([]byte(deployScript(strings.TrimPrefix(name, "scripts/"))), &definitions); err != nil {
			return err
		}
		for key, command := range definitions {
			if _, exists := commands[key]; exists {
				return fmt.Errorf("duplicate deploy command: %s", key)
			}
			commands[key] = command
		}
		return nil
	})
	if err != nil {
		panic(err)
	}
	return commands
}()

var deployArgument = regexp.MustCompile(`\$\{([1-9][0-9]*)\}`)

// $1/$2 select complete argv entries; ${1} substitutes inside one entry.
// $* inserts all caller-provided argv. None of these values are shell text.
func deployCommand(name string, args ...string) []string {
	source, ok := deployCommands[name]
	if !ok || len(source) == 0 {
		panic("missing deploy command: " + name)
	}
	var command []string
	for _, value := range source {
		if value == "$*" {
			command = append(command, args...)
		} else if strings.HasPrefix(value, "$") && !strings.HasPrefix(value, "${") {
			index, err := strconv.Atoi(value[1:])
			if err != nil || index < 1 || index > len(args) {
				panic("invalid argument for deploy command: " + name)
			}
			command = append(command, args[index-1])
		} else {
			command = append(command, deployArgument.ReplaceAllStringFunc(value, func(placeholder string) string {
				index, _ := strconv.Atoi(placeholder[2 : len(placeholder)-1])
				if index > len(args) {
					panic("invalid argument for deploy command: " + name)
				}
				return args[index-1]
			}))
		}
	}
	return command
}

func (x *executor) sourceSoftwareCommand(ctx context.Context, name string, args ...string) ([]byte, error) {
	command := deployCommand(name, args...)
	return x.softwareRunner(ctx, command[0], command[1:]...)
}

func (x *executor) loggedSourceCommand(ctx context.Context, req Request, phase, name string, args ...string) ([]byte, error) {
	command := deployCommand(name, args...)
	return x.loggedSoftwareCommand(ctx, req, phase, command[0], command[1:]...)
}

func (x *executor) serviceDockerSource(req Request, phase string, limit time.Duration, name string, args ...string) ([]byte, error) {
	command := deployCommand(name, args...)
	if command[0] != "/usr/bin/docker" {
		panic("non-Docker source for serviceDocker: " + name)
	}
	return x.serviceDocker(req, phase, limit, command[1:]...)
}
